def matches(events):
    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    # Iterate through each event to check if it matches the criteria
    for i in range(len(events)):
        current_event = events[i]

        # Check if there is an overlapping or simultaneous event with the same type
        for j in range(i+1, len(events)):
            other_event = events[j]

            if current_event['type'] == 'TURN' and other_event['type'] == 'DECELERATE':
                if overlap(current_event, other_event) <= 0.5:
                    return True

            elif current_event['type'] == 'DECELERATE' and other_event['type'] == 'ACCELERATE':
                if overlap(current_event, other_event) > 0.5 and overlap(current_event, other_event) >= 0.8 * min(current_event['duration'], other_event['duration']):
                    return True

    return False

