        for j in range(i + 1, len(events)):
            event_i = events[i]
            event_j = events[j]

            if event_i['type'] == 'TURN' and event_j['type'] == 'DECELERATE':
                if turn_then_decelerate(event_i, event_j):
                    return True

    return False
