def matches(events) -> bool:
    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    # Iterate through each event to check if it meets the criteria
    for i in range(len(events)):
        current_event = events[i]

        # Check if the next event overlaps with this one or if they both accelerate/decelerate at the same time
        for j in range(i+1, len(events)):
            next_event = events[j]

            if current_event["type"] == "ACCELERATE":
                if next_event["type"] == "DECELERATE":
                    return True

            elif current_event["type"] == "DECELERATE":
                if next_event["type"] == "ACCELERATE":
                    return True

            # Check if the events overlap within the allowed margin
            if current_event["type"] != "STOP":
                overlap = max(0, min(current_event['end'], next_event['end']) - max(current_event['start'], next_event['start']))

                if overlap <= 0.5:
                    continue

                if -0.5 <= next_event['start'] - current_event['end'] <= 5.0:
                    return True

    return False
