def matches(events):
    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    # Iterate through each event to check if it matches any other event
    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            # Check if the current event overlaps with another event
            if events[i]['start'] <= events[j]['start']:
                continue

            # Calculate overlap between the two events
            overlap = max(0, min(events[i]['end'], events[j]['end']) - max(events[i]['start'], events[j]['start']))

            # If there is an overlap greater than or equal to 0.8 * min(duration(A), duration(B)), they match
            if overlap >= 0.8 * min((events[i]['end'] - events[i]['start']), (events[j]['end'] - events[j]['start'])):
                return True

    # If no matching pairs were found, return False
    return False

